#include <stdio.h>

#define FILE_NAME "input.txt"
#define MAX_LEN 100

/* 判分环境下先把标准输入的全部内容写成 input.txt，充当题面里"命令行给出的那个文件" */
static void prepare_file(void)
{
    FILE *fp = fopen(FILE_NAME, "w");
    int ch;

    if (fp == NULL)
        return;
    while ((ch = getchar()) != EOF)
        fputc(ch, fp);
    fclose(fp);
}

/* 从 fp 中读入一行（最多 max 个字符，不含换行符），返回读入的字符个数 */
int get_line(char *str, int max, FILE *fp)
{
    int n = 0;
    int ch;

    while (n < max && (ch = fgetc(fp)) != EOF && ch != '\n') {
        str[n] = (char)ch;
        n = n + 1;
    }
    str[n] = '\0';

    return n;
}

int main(void)
{
    char str[MAX_LEN + 1];
    FILE *fp;
    int len;

    prepare_file();

    fp = fopen(FILE_NAME, "r");
    if (fp == NULL) {
        printf("str=\nlen=0\n");
        return 0;
    }
    len = get_line(str, MAX_LEN, fp);
    fclose(fp);

    printf("str=%s\n", str);
    printf("len=%d\n", len);

    return 0;
}

#include <stdio.h>

#define SRC_NAME "input.txt"
#define DST_NAME "output.txt"

/* 判分环境下先把标准输入的全部内容写成源文件 input.txt */
static void prepare_src(void)
{
    FILE *fp = fopen(SRC_NAME, "w");
    int ch;

    if (fp == NULL)
        return;
    while ((ch = getchar()) != EOF)
        fputc(ch, fp);
    fclose(fp);
}

int main(void)
{
    FILE *in, *out;
    int ch;
    long copied = 0;

    prepare_src();

    in = fopen(SRC_NAME, "rb");
    if (in == NULL) {
        printf("copied=0\n");
        return 0;
    }
    out = fopen(DST_NAME, "wb");
    if (out == NULL) {
        fclose(in);
        printf("copied=0\n");
        return 0;
    }

    /* 逐字节复制 */
    while ((ch = fgetc(in)) != EOF) {
        fputc(ch, out);
        copied = copied + 1;
    }
    fclose(in);
    fclose(out);

    printf("copied=%ld\n", copied);

    /* 原样回显目的文件内容，不额外添加换行 */
    out = fopen(DST_NAME, "rb");
    if (out != NULL) {
        while ((ch = fgetc(out)) != EOF)
            putchar(ch);
        fclose(out);
    }

    return 0;
}

#include <stdio.h>

#define FILE_NAME "number.dat"

/* 判分环境下先把标准输入的全部内容写成 number.dat */
static void prepare_file(void)
{
    FILE *fp = fopen(FILE_NAME, "w");
    int ch;

    if (fp == NULL)
        return;
    while ((ch = getchar()) != EOF)
        fputc(ch, fp);
    fclose(fp);
}

int main(void)
{
    FILE *fp;
    int x;
    int positive = 0, zero = 0, negative = 0;

    prepare_file();

    fp = fopen(FILE_NAME, "r");
    if (fp != NULL) {
        while (fscanf(fp, "%d", &x) == 1) {
            if (x > 0)
                positive = positive + 1;
            else if (x < 0)
                negative = negative + 1;
            else
                zero = zero + 1;
        }
        fclose(fp);
    }

    printf("positive=%d zero=%d negative=%d\n", positive, zero, negative);

    return 0;
}

#include <stdio.h>

#define FILE_NAME "student.dat"

struct student
{
    long int num;        /* 学号 */
    char name[10];       /* 姓名 */
    int age;             /* 年龄 */
    char sex;            /* 性别 */
    char speciality[20]; /* 专业 */
    char addr[40];       /* 住址 */
};

/* 判分环境下先按字段顺序从标准输入建好二进制文件 student.dat */
static void prepare_file(void)
{
    FILE *fp = fopen(FILE_NAME, "wb");
    struct student s;

    if (fp == NULL)
        return;
    while (scanf("%ld %9s %d %c %19s %39s", &s.num, s.name, &s.age, &s.sex,
                 s.speciality, s.addr) == 6)
        fwrite(&s, sizeof(s), 1, fp);
    fclose(fp);
}

int main(void)
{
    FILE *fp;
    struct student s;
    int found = 0;

    prepare_file();

    fp = fopen(FILE_NAME, "rb");
    if (fp == NULL) {
        printf("none\n");
        return 0;
    }
    while (fread(&s, sizeof(s), 1, fp) == 1) {
        if (s.num >= 40101 && s.num <= 40135) {
            printf("%06ld %s %d %c\n", s.num, s.name, s.age, s.sex);
            found = 1;
        }
    }
    fclose(fp);

    if (!found)
        printf("none\n");

    return 0;
}

